"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50061"],{55055(e){e.exports=JSON.parse('{"id":"F244","slug":"fee-drag","name":"Cost of Fees: Active vs. Passive","subject":"Investments & Portfolio Theory","section":"Market Efficiency","topic":"Active vs. passive management debate","level":"Beginner","aliases":["expense ratio impact","fee drag","active versus passive","cost of active management"],"formula":{"latex":"FV=P\\\\,(1+r-f)^{n}","also":[],"text":"Final value = Amount invested x (1 + gross return - annual fee)^years"},"symbols":[{"symbol":"FV","meaning":"Final value of the investment","unit":"money"},{"symbol":"P","meaning":"Amount invested at the start","unit":"money"},{"symbol":"r","meaning":"Gross return before fees, per year","unit":"per year"},{"symbol":"f","meaning":"Annual fee as a percentage of assets","unit":"per year"},{"symbol":"n","meaning":"Years","unit":"years"}],"when_to_use":"Use it to see what fees cost over time. Because fees come out of the balance each year, they compound too. An active fund must earn more than its passive rival, by at least the fee difference, just to match it.","worked_example":{"problem":"You invest 10,000 for 30 years. Before fees the market returns 7% a year. An active fund charges 1.0% and an index fund charges 0.1%. Both earn the market return before fees. What is each worth at the end?","inputs":{"p":10000,"r":7,"fa":1,"fp":0.1,"n":30},"steps":[{"label":"Active fund value = P x (1 + r - fa)^n","working":"10000 x (1+0.07-0.01)^30","value":"57,434.91"},{"label":"Index fund value = P x (1 + r - fp)^n","working":"10000 x (1+0.07-0.001)^30","value":"74,016.95"},{"label":"Cost of the extra fee = index value - active value","working":"74016.9-57434.9","value":"16,582.03"},{"label":"As a share of the index fund value","working":"16582 / 74016.9","value":"22.40%"},{"label":"Break-even outperformance per year = fa - fp","working":"0.01-0.001","value":"0.90%"}],"answer":"The active fund grows to 57,434.91 and the index fund to 74,016.95. The fee difference costs 16,582.03, or 22.40% of the index fund\'s result. The active manager must beat the market by 0.90% a year just to break even."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Amount invested","unit":"money","type":"number","default":10000,"hint":""},{"id":"r","label":"Gross annual return","unit":"%","type":"number","default":7,"hint":""},{"id":"fa","label":"Active fund fee","unit":"%","type":"number","default":1,"hint":""},{"id":"fp","label":"Index fund fee","unit":"%","type":"number","default":0.1,"hint":""},{"id":"n","label":"Years","unit":"years","type":"number","default":30,"hint":"","min":1}],"checks":[],"steps":[{"id":"fva","label":"Active fund value = P x (1 + r - fa)^n","expr":"p*(1+r-fa)^n","format":"money"},{"id":"fvp","label":"Index fund value = P x (1 + r - fp)^n","expr":"p*(1+r-fp)^n","format":"money"},{"id":"loss","label":"Cost of the extra fee = index value - active value","expr":"fvp-fva","format":"money"},{"id":"pct","label":"As a share of the index fund value","expr":"loss/fvp","format":"pct2"},{"id":"be","label":"Break-even outperformance per year = fa - fp","expr":"fa-fp","format":"pct2"}],"results":["fva","fvp","loss"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"fva":57434.91172913258,"fvp":74016.94505951238,"loss":16582.033330379796}},"finder":{"finds":"How fees reduce wealth over time","needs":"Amount, gross return, two fees, years"},"related":[{"slug":"fv-lump-sum","name":"Future Value of a Lump Sum"},{"slug":"jensens-alpha","name":"Jensen\'s Alpha"}],"related_ids":["F011","F247"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>F</mi><mi>V</mi><mo>=</mo><mi>P</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo>\u2212</mo><mi>f</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup></mrow><annotation encoding=\\"application/x-tex\\">FV=P\\\\,(1+r-f)^{n}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>F</mi><mi>V</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle FV</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>P</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo>\u2212</mo><mi>f</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =P\\\\,(1+r-f)^{n}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"mm-cost-of-equity","name":"Cost of Equity with Leverage (Modigliani-Miller Proposition II)"},"next":{"slug":"cost-of-goods-sold","name":"Cost of Goods Sold (Inventory Roll-Forward)"},"lesson":null,"total":522}')}}]);